/* APLUS AI Tutor Database V1 — P6 Synthesis & Transformation Expansion Batch 04 */
window.APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH04 = [
{id:"P6-ST-B04-001",type:"synthesis",skill:"although",question:"The road was crowded. We arrived on time. Begin: Although...",answer:"Although the road was crowded, we arrived on time.",acceptedPatterns:["Although the road was crowded, we arrived on time.","Although the road was crowded, we still arrived on time."],explanation:"Although joins two contrasting ideas.",difficulty:3},
{id:"P6-ST-B04-002",type:"synthesis",skill:"because",question:"The floor was wet. The cleaner had just mopped it. Begin: The floor was wet because...",answer:"The floor was wet because the cleaner had just mopped it.",acceptedPatterns:["The floor was wet because the cleaner had just mopped it."],explanation:"Because introduces the reason.",difficulty:3},
{id:"P6-ST-B04-003",type:"synthesis",skill:"so",question:"The alarm rang. Everyone left the building. Begin: The alarm rang, so...",answer:"The alarm rang, so everyone left the building.",acceptedPatterns:["The alarm rang, so everyone left the building."],explanation:"So introduces the result.",difficulty:2},
{id:"P6-ST-B04-004",type:"synthesis",skill:"after",question:"Jane finished her homework. She watched television. Begin: After...",answer:"After Jane finished her homework, she watched television.",acceptedPatterns:["After Jane finished her homework, she watched television.","Jane watched television after she finished her homework."],explanation:"After links the earlier action to the later action.",difficulty:3},
{id:"P6-ST-B04-005",type:"synthesis",skill:"before",question:"The guests arrived. We prepared the food. Begin: Before...",answer:"Before the guests arrived, we prepared the food.",acceptedPatterns:["Before the guests arrived, we prepared the food.","We prepared the food before the guests arrived."],explanation:"Before establishes the earlier action.",difficulty:3},
{id:"P6-ST-B04-006",type:"synthesis",skill:"while",question:"I was reading. My sister was drawing. Begin: While...",answer:"While I was reading, my sister was drawing.",acceptedPatterns:["While I was reading, my sister was drawing.","My sister was drawing while I was reading."],explanation:"While can connect two actions happening at the same time.",difficulty:3},
{id:"P6-ST-B04-007",type:"synthesis",skill:"relative clause",question:"I met a girl. She won the writing competition. Begin: I met a girl...",answer:"I met a girl who won the writing competition.",acceptedPatterns:["I met a girl who won the writing competition."],explanation:"Who introduces a relative clause referring to a person.",difficulty:3},
{id:"P6-ST-B04-008",type:"synthesis",skill:"relative clause",question:"We visited a museum. It displayed ancient maps. Begin: We visited a museum...",answer:"We visited a museum which displayed ancient maps.",acceptedPatterns:["We visited a museum which displayed ancient maps.","We visited a museum that displayed ancient maps."],explanation:"Which or that can introduce a defining relative clause referring to a thing.",difficulty:3},
{id:"P6-ST-B04-009",type:"synthesis",skill:"unless",question:"You must wear shoes. You cannot enter the laboratory. Begin: Unless...",answer:"Unless you wear shoes, you cannot enter the laboratory.",acceptedPatterns:["Unless you wear shoes, you cannot enter the laboratory.","You cannot enter the laboratory unless you wear shoes."],explanation:"Unless means if not.",difficulty:4},
{id:"P6-ST-B04-010",type:"synthesis",skill:"because of",question:"The match was postponed. There was heavy rain. Begin: The match was postponed because of...",answer:"The match was postponed because of the heavy rain.",acceptedPatterns:["The match was postponed because of the heavy rain.","The match was postponed because of heavy rain."],explanation:"Because of is followed by a noun phrase.",difficulty:3},
{id:"P6-ST-B04-011",type:"synthesis",skill:"despite",question:"It was raining heavily. The hikers continued. Begin: Despite...",answer:"Despite the heavy rain, the hikers continued.",acceptedPatterns:["Despite the heavy rain, the hikers continued.","Despite the heavy rain, the hikers continued their walk."],explanation:"Despite is followed by a noun phrase or gerund phrase and expresses contrast.",difficulty:4},
{id:"P6-ST-B04-012",type:"synthesis",skill:"so that",question:"Liam spoke loudly. Everyone could hear him. Begin: Liam spoke loudly so that...",answer:"Liam spoke loudly so that everyone could hear him.",acceptedPatterns:["Liam spoke loudly so that everyone could hear him."],explanation:"So that expresses purpose.",difficulty:3},
{id:"P6-ST-B04-013",type:"transformation",skill:"too...to",question:"The box was so heavy that I could not lift it. Rewrite using too...to.",answer:"The box was too heavy for me to lift.",acceptedPatterns:["The box was too heavy for me to lift.","The box was too heavy to lift."],explanation:"Too + adjective + to-infinitive expresses an excessive degree that prevents an action.",difficulty:4},
{id:"P6-ST-B04-014",type:"transformation",skill:"enough",question:"The ladder was sufficiently long for us to reach the roof. Rewrite using enough.",answer:"The ladder was long enough for us to reach the roof.",acceptedPatterns:["The ladder was long enough for us to reach the roof."],explanation:"Enough follows the adjective when it means sufficient in degree.",difficulty:3},
{id:"P6-ST-B04-015",type:"transformation",skill:"passive voice",question:"The chef prepared the meal. Rewrite in the passive voice.",answer:"The meal was prepared by the chef.",acceptedPatterns:["The meal was prepared by the chef.","The meal was prepared by the chef."],explanation:"Move the object to subject position and use the past passive form.",difficulty:3},
{id:"P6-ST-B04-016",type:"transformation",skill:"reported speech",question:"Tom said, “I have finished my project.” Rewrite as reported speech.",answer:"Tom said that he had finished his project.",acceptedPatterns:["Tom said that he had finished his project.","Tom said he had finished his project."],explanation:"The pronoun changes from I to he and present perfect changes to past perfect in the past reporting context.",difficulty:4},
{id:"P6-ST-B04-017",type:"transformation",skill:"reported question",question:"Sara asked, “Where is the library?” Rewrite as reported speech.",answer:"Sara asked where the library was.",acceptedPatterns:["Sara asked where the library was."],explanation:"Reported questions use statement word order and backshift where appropriate.",difficulty:4},
{id:"P6-ST-B04-018",type:"transformation",skill:"reported command",question:"The teacher said to us, “Close the windows.” Rewrite as reported speech.",answer:"The teacher told us to close the windows.",acceptedPatterns:["The teacher told us to close the windows."],explanation:"A reported command commonly uses told + object + to-infinitive.",difficulty:4},
{id:"P6-ST-B04-019",type:"transformation",skill:"comparative",question:"The blue bag is not as heavy as the black bag. Rewrite using comparative form.",answer:"The black bag is heavier than the blue bag.",acceptedPatterns:["The black bag is heavier than the blue bag."],explanation:"Not as...as can be transformed into a comparative relationship.",difficulty:3},
{id:"P6-ST-B04-020",type:"transformation",skill:"purpose",question:"Mina saved money because she wanted to buy a bicycle. Rewrite using so that.",answer:"Mina saved money so that she could buy a bicycle.",acceptedPatterns:["Mina saved money so that she could buy a bicycle."],explanation:"So that + could expresses purpose in a past context.",difficulty:4}
];